	@Override
	public MCCallerPanelBridge createBridge(String id) {
		if (id.equals("MG.MGBFL0300.Srch01")) {
			return new MG_MGBFL0300_Srch01Bridge();
		}
		if (id.equals("MG.MGBFL0300.Upd01")) {
			return new MG_MGBFL0300_Upd01Bridge();
		}
		return super.createBridge(id);
	}
